-- General-knowledge albums (drawn in packages/shared/src/knowledgeArt.ts).
-- The football albums stay; the new albums come first in the album list.
update public.albums set sort = sort + 100 where sort < 100;
on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, sort = excluded.sort, kind = excluded.kind;

on conflict (id) do update set name_he = excluded.name_he, rarity = excluded.rarity, bio_he = excluded.bio_he, album = excluded.album, number = excluded.number;
